import { pixelBasedPreset, type TailwindConfig } from "react-email";

// Central brand configuration. Update colors here — templates pick them up automatically.
const tailwindConfig = {
  presets: [pixelBasedPreset],
  theme: {
    extend: {
      colors: {
        brand: {
          // Primary CTA color (buttons, key accents)
          primary: "#18181b",
          // Foreground on primary (button text)
          primaryFg: "#ffffff",
          // Muted links, secondary labels
          muted: "#71717a",
          // Body text
          body: "#3f3f46",
          // Heading text
          heading: "#09090b",
          // Dividers and borders
          border: "#e4e4e7",
          // Email body background
          bg: "#f4f4f5",
          // Card / container background
          surface: "#ffffff",
          // Warning box background (security notices, expiry)
          warnBg: "#fffbeb",
          // Warning box text
          warnText: "#92400e",
          // Info box background (login details, metadata)
          infoBg: "#eff6ff",
          // Info box text
          infoText: "#1e40af",
        },
      },
    },
  },
} satisfies TailwindConfig;

export default tailwindConfig;

// Brand assets — update src to your production CDN URL.
export const brand = {
  name: "Your Company",
  // Logo: 160×40px PNG hosted on a CDN. Leave empty to show text name instead.
  logoSrc: "",
  logoAlt: "Your Company",
  logoWidth: 120,
  logoHeight: 32,
  // CAN-SPAM / KVKK required: physical mailing address.
  address: "Your Company · 123 Main Street · City, Country",
  // Base URL for generating links in PreviewProps
  baseUrl: "https://yourcompany.com",
};

import * as React from "react";
import {
  Body,
  Container,
  Head,
  Hr,
  Html,
  Img,
  Link,
  Preview,
  Section,
  Tailwind,
  Text,
} from "react-email";
import tailwindConfig, { brand } from "../tailwind.config";

export interface EmailLayoutProps {
  preview: string;
  children: React.ReactNode;
  companyName?: string;
  /** Absolute URL to your logo PNG. Falls back to text name. */
  logoSrc?: string;
  logoAlt?: string;
  /** Physical address for CAN-SPAM / KVKK footer. */
  companyAddress?: string;
  unsubscribeUrl?: string;
}

export function EmailLayout({
  preview,
  children,
  companyName = brand.name,
  logoSrc = brand.logoSrc,
  logoAlt = brand.logoAlt,
  companyAddress = brand.address,
  unsubscribeUrl,
}: EmailLayoutProps) {
  const year = new Date().getFullYear();

  return (
    <Html lang="en">
      <Tailwind config={tailwindConfig}>
        <Head />
        <Body className="bg-brand-bg font-sans m-0 p-0">
          <Preview>{preview}</Preview>

          <Container className="bg-brand-surface mx-auto my-[40px] rounded-[8px] max-w-[560px]">
            {/* Header — logo or company name */}
            <Section className="px-[40px] pt-[36px] pb-[24px]">
              {logoSrc ? (
                <Img
                  src={logoSrc}
                  alt={logoAlt}
                  width={brand.logoWidth}
                  height={brand.logoHeight}
                  className="block"
                />
              ) : (
                <Text className="text-[18px] font-bold text-brand-heading m-0 leading-[24px] tracking-tight">
                  {companyName}
                </Text>
              )}
            </Section>

            <Hr className="border-none border-t-[1px] border-solid border-brand-border mx-[40px] my-0" />

            {/* Content slot */}
            <Section className="px-[40px] py-[36px]">{children}</Section>

            {/* Footer */}
            <Hr className="border-none border-t-[1px] border-solid border-brand-border mx-[40px] my-0" />
            <Section className="px-[40px] py-[24px]">
              <Text className="text-[12px] text-brand-muted m-0 leading-[18px] text-center">
                {companyAddress}
              </Text>
              <Text className="text-[12px] text-brand-muted mt-[6px] mb-0 text-center">
                {`© ${year} ${companyName}`}
              </Text>
              {unsubscribeUrl ? (
                <Text className="text-[12px] text-brand-muted mt-[6px] mb-0 text-center">
                  <Link
                    href={unsubscribeUrl}
                    className="text-brand-muted underline"
                  >
                    Unsubscribe
                  </Link>
                </Text>
              ) : null}
            </Section>
          </Container>
        </Body>
      </Tailwind>
    </Html>
  );
}

export default EmailLayout;

import * as React from "react";
