  companyName?: string;
}

export function VerifyEmail({
  verificationUrl,
  userEmail,
  expiresInMinutes = 60,
  companyName = brand.name,
}: VerifyEmailProps) {
  return (
    <EmailLayout preview="Confirm your email address" companyName={companyName}>
